function defaultColors(template: TemplateId): Record<string, string> {
  const t =
    TEMPLATES.find((x) => x.id === template) ?? TEMPLATES.find((x) => x.id === DEFAULTS.TEMPLATE)!;
  return Object.fromEntries(t.slots.map((s) => [s.key, s.default]));
}

